// Routes lists every legacy route this package's contracts serve.
func Routes() []string {
	var routes []string
	routes = append(routes, CompatibilityServiceRoutes()...)
	return routes
}

// HTTPRoutes lists the routes served by @http methods: the original
// handler runs, route middlewares included.
func HTTPRoutes() []string {
	return []string{"POST /hr/reports/generate"}
}

// Register serves this package's contracts on mux from the route table,
// with the legacy request body limit and error shape.
func Register(mux *http.ServeMux, routes *serverHttp.LegacyRoutes) error {
	writeError := hrcompatv1.WithErrorWriter(func(w http.ResponseWriter, r *http.Request, e *hrcompatv1.ServerError) {
		status, _, message, _, violations, cause := e.Parts()
		serverHttp.WriteContractError(w, r, status, message, violations, cause)
	})
	if err := hrcompatv1.RegisterCompatibilityServiceServer(CompatibilityService{Routes: routes}, hrcompatv1.WithMux(mux),
		hrcompatv1.WithMaxRequestBodyBytes(serverHttp.DefaultMaxRequestBodyBytes), writeError); err != nil {
		return err
	}
	return nil
}
